SELECT *, SUM(rating) OVER (PARTITION BY city, country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_rating, NTILE(10) OVER (PARTITION BY country ORDER BY rating, id) AS rating_bucket, LAST_VALUE(city, TRUE) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_city, ROW_NUMBER() OVER (PARTITION BY country ORDER BY rating DESC, id) AS event_seq, NTILE(4) OVER (PARTITION BY country ORDER BY rating DESC, id) AS rating_bucket_2 FROM suppliers;
